{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Phytoene, a highly lipophilic C40 isoprenoid carotenoid with no ionizable groups, showed an absolute oral bioavailability of 58.5 ± 18.9% in humans, directly supporting that long-chain isoprenoid lipids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Cis isomers of lycopene, another highly lipophilic C40 carotenoid, exhibited 24.5% ± 6% oral bioavailability in healthy subjects, providing threshold-relevant evidence that large lipophilic isoprenoids can be absorbed to a meaningful extent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Hyperforin, a polyprenylated lipophilic natural product, showed high oral bioavailability in volunteers, supporting the transferability of high absorption to prenylated lipophilic molecules despite poor aqueous solubility.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "The most relevant experimental analogues—long-chain isoprenoid carotenoids and a polyprenylated natural product—consistently show oral bioavailability at or above 20% in humans. Although the query's extreme lipophilicity and high molecular weight raise absorption concerns, the supportive experimental evidence outweighs the physicochemical prior, leading to a high prediction with low confidence due to size and formulation differences.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the query molecule itself.",
    "The closest analogues are substantially smaller (MW ~536 vs 863 Da), so size-dependent absorption differences remain uncertain.",
    "Formulation, food effects, and lymphatic absorption contributions are not fully captured by the available evidence.",
    "First-pass metabolism and intestinal extraction for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

